import { MATERIALS,SOURCES } from './materials.js';
import { resourceHTML,responseLayout,lessonFormat,TEACHER_NOTES } from './lesson-layouts.js';
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function renderLessonDocument(teacher=false){return `<!doctype html><html lang="de"><meta charset="utf-8"><title>Ranger Kompakt · ${teacher?'Lehrkräfte':'Arbeitsblätter'}</title><style>body{font:14px/1.5 system-ui;max-width:850px;margin:30px auto;padding:20px;color:#263c32}article{border-top:1px solid #aaa;margin:30px 0}h1,h2{font-family:Georgia;font-weight:400}a{color:#295842;overflow-wrap:anywhere}table{border-collapse:collapse;width:100%;margin:12px 0;font-size:12px}th,td{border:1px solid #83988a;padding:7px;text-align:left;vertical-align:top}caption{text-align:left;font-weight:600}.work-table td{height:32px}.writing{height:90px;border-bottom:1px solid #8c9f92;background:repeating-linear-gradient(white,white 28px,#ccd6cf 29px,white 30px)}svg{width:100%;max-height:200px}thead{display:table-header-group}tr,svg{break-inside:avoid}h3,h2{break-after:avoid}@media print{article{break-before:page}body{margin:0;padding:0}.writing{height:100px}}</style><body><h1>Ranger Kompakt · ${teacher?'Lehrkräftefassung mit Erwartung und Rückmeldung':'Arbeitsblätter und Quellen'}</h1><p>Gestaltetes Modell, keine Naturmessung. Freie Erklärungen fachlich besprechen; keine automatische Stichwortbenotung. Pro Kernfamilie 20–35 Minuten als ungeprüftes Planungsziel. Kein Gesamtsammelzwang.</p><p>Die drei Ebenen getrennt erfassen: 1 curricular zugeordnet; 2 Lernangebot vorhanden; 3 konkrete Leistung erhoben/besprochen. Eine vorhandene Karte erfüllt nur Ebene 2. Ebene 3 braucht das ausgefüllte Arbeitsprodukt und eine fachliche Rückmeldung.</p><p>Zuordnung nach übergebenen Zusammenfassungen: ETS 2025/26 S.27–28, FA SH 2026 S.50–55/62, Leitfaden 2017 S.47–49. Original-PDFs lagen nicht vor. Tabellen sind lokal nutzbar; externe Originale und aktuelle Daten können eine weitere Quellenprüfung verlangen.</p>${MATERIALS.map(c=>{const notes=TEACHER_NOTES[c.id],expect=notes?[...c.expected,notes[0]]:c.expected;return `<article data-card="${c.id}" data-product="${lessonFormat(c)}"><p>${c.id} · ${e(c.level)} · ${e(c.activity)}</p><h2>${e(c.title)}</h2><h3>Material / Herkunft</h3><p>${e(c.data)}</p>${resourceHTML(c,e)}<h3>Auftrag</h3><p>${e(c.task)}</p>${c.helps?'<h3>Hilfen</h3><ol>'+c.helps.map(h=>'<li>'+e(h)+'</li>').join('')+'</ol>':''}<h3>Mein Arbeitsprodukt</h3>${responseLayout(c)}${teacher?'<h3>Erwartung, Alternativen und Rückmeldung</h3><ul>'+expect.map(x=>'<li>'+e(x)+'</li>').join('')+'</ul><p>Fachlich begründete andere Formulierungen und Unsicherheit zulassen; offene Texte nicht per Stichwort benoten.</p><p><strong>Typische Fehlvorstellung:</strong> '+e(c.pitfall||notes?.[1]||'Programmregel mit unabhängig bestätigter Naturbeobachtung gleichsetzen.')+'</p><p><strong>Rückmeldung:</strong> '+e(c.feedback||notes?.[2]||'Eine Aussage einem konkreten Beleg und seiner Herkunft zuordnen lassen.')+'</p>':''}<p><strong>Grenze:</strong> ${e(c.limit)}</p>${c.sources.map(k=>`<p>${e(SOURCES[k].title)}: <a href="${e(SOURCES[k].url)}">${e(SOURCES[k].url)}</a></p>`).join('')}<p>Leistungsnachweis: □ noch nicht erhoben □ Arbeitsprodukt vorhanden □ fachlich besprochen. Datum / Rückmeldung: __________</p></article>`;}).join('')}<h2>Unterrichtspilot: noch durchzuführen</h2><p>Zielgerät laut Auftrag: Apple iPad 9, Safari, iPadOS 27; in der Cloud nicht physisch geprüft. Im Pilot anonym Bearbeitungszeit, Hilfebedarf, Aufgabenverständnis, neue Transferantwort und Ausfälle erfassen. Keine Namen, Anmeldung oder Cloudübermittlung. Reale Exkursion und Gerätekompetenz gesondert prüfen.</p></body></html>`;}
